package com.example.studentregistration.data

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Room entity - one row in the "students" table.
 * studentId is auto-generated by SQLite (1, 2, 3 ...) so the user never types it,
 * which satisfies "Student ID (can be autogenerated)".
 */
@Entity(tableName = "students")
data class Student(
    @PrimaryKey(autoGenerate = true) val studentId: Int = 0,
    val name: String,
    val course: String,
    val year: Int
)
